const r=await tools.exec_command({cmd:"python3 - <<'PY'
import hashlib, json, pathlib, subprocess, os
root = pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
out = pathlib.Path(os.environ['STAMPED_JUDGE_OUTPUT']) / 'remote-check' / 'neurovault-all-maps-attempt-2'
out.mkdir(parents=True, exist_ok=True)
sources = json.loads((root / 'input/sources.json').read_text())
rows=[]
for rel,item in sources['files'].items():
    if not rel.endswith('.nii.gz'):
        continue
    dest=out/pathlib.Path(rel).name
    c=subprocess.run(['curl','--location','--fail','--silent','--show-error','--max-time','60','--output',str(dest),item['url']],capture_output=True,text=True)
    row={'path':rel,'url':item['url'],'expected_bytes':item['bytes'],'expected_sha256':item['sha256'],'returncode':c.returncode,'stderr':c.stderr}
    if c.returncode==0:
        b=dest.read_bytes(); h=hashlib.sha256(b).hexdigest(); row.update(retrieved_bytes=len(b),retrieved_sha256=h,byte_match=len(b)==item['bytes'],sha256_match=h==item['sha256'])
    rows.append(row)
    print(json.dumps({k:row.get(k) for k in ('path','returncode','retrieved_bytes','byte_match','sha256_match','stderr')}),flush=True)
manifest={'route':'sources.json direct NeuroVault media URLs via curl','recipient':'researcher using declared authorized access route','host_scope':'assessor host; direct source fetch, not cross-host test','required_coverage':'all 54 participant gain-effect maps','retrieved':sum(r.get('sha256_match',False) for r in rows),'attempted':len(rows),'files':rows}
(out/'retrieval-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
